// === Tab: main ===
// ============================================================
// Navier-let function Simulation(Processing)
// let on let Stam's "Real-Time Fluid Dynamics for Games"
// ============================================================

let fluidSolver;
let fluidViscosity, fluidDiffusion, velocityScaleFactor, particleVelocityScale;
let maxMouseVelocity;
let previousMouseX = 1, previousMouseY = 1;
let numberOfParticles;
let particles;
let particleColor = color(255, 255, 255);

function setup() {
  // A3竖版比例 (宽:高 = 1:√2)
  createCanvas(800, 1131);
  background(0, 200, 230); // 青蓝色背景

  fluidSolver = new NavierStokesFluidSolver();
  numberOfParticles = int(pow)(2, 16); // 65536
  particles = new Array(numberOfParticles);
  fluidViscosity = 0.00059;
  fluidDiffusion = 0.03;
  velocityScaleFactor = 10;
  maxMouseVelocity = 10;
  initializeParticles();
}

function initializeParticles() {
  for (i = 0; i < numberOfParticles; i++) {
    particles[i] = new Particle();
    particles[i].x = random(width);
    particles[i].y = random(height);
  }
}

function draw() {
  updateMouseInteraction();
  clearCanvas();
  let timeStep = 1.0 / frameRate;
  fluidSolver.updateSimulation(timeStep, fluidViscosity, fluidDiffusion);
  particleVelocityScale = velocityScaleFactor * 60.0 / frameRate;
  renderParticles();
}

function clearCanvas() {
  fill(0, 200, 230); // 青蓝色
  rect(0, 0, width, height);
}

function renderParticles() {
  let gridSize = NavierStokesFluidSolver.GRID_SIZE;
  let cellHeight = height / gridSize;
  let cellWidth = width / gridSize;

  for (let particle of particles) {
    if (particle != null) {
      let cellX = floor(particle.x / cellWidth);
      let cellY = floor(particle.y / cellHeight);

      let velocityX = float(fluidSolver.getVelocityX)(cellX, cellY);
      let velocityY = float(fluidSolver.getVelocityY)(cellX, cellY);

      let localX = particle.x - cellX * cellWidth - cellWidth / 2;
      let localY = particle.y - cellY * cellHeight - cellHeight / 2;

      let neighborX, neighborY, xDirection, yDirection;
      if (localX > 0) {
        neighborX = Math.min(gridSize, cellX + 1);
        xDirection = 1;
      } else {
        neighborX = Math.max(0, cellX - 1);
        xDirection = -1;
      }
      if (localY > 0) {
        neighborY = Math.min(gridSize, cellY + 1);
        yDirection = 1;
      } else {
        neighborY = Math.max(0, cellY - 1);
        yDirection = -1;
      }

      let vxNx = float(fluidSolver.getVelocityX)(neighborX, cellY);
      let vxNy = float(fluidSolver.getVelocityX)(cellX, neighborY);
      let vxNxy = float(fluidSolver.getVelocityX)(neighborX, neighborY);
      let vyNx = float(fluidSolver.getVelocityY)(neighborX, cellY);
      let vyNy = float(fluidSolver.getVelocityY)(cellX, neighborY);
      let vyNxy = float(fluidSolver.getVelocityY)(neighborX, neighborY);

      velocityX = lerp(
        lerp(velocityX, vxNx, xDirection * localX / cellWidth),
        lerp(vxNy, vxNxy, xDirection * localX / cellWidth),
        yDirection * localY / cellHeight
      );
      velocityY = lerp(
        lerp(velocityY, vyNx, xDirection * localX / cellWidth),
        lerp(vyNy, vyNxy, xDirection * localX / cellWidth),
        yDirection * localY / cellHeight
      );

      particle.x += velocityX * particleVelocityScale;
      particle.y += velocityY * particleVelocityScale;

      if (particle.x < 0 || particle.x >= width) {
        particle.x = random(width);
      }
      if (particle.y < 0 || particle.y >= height) {
        particle.y = random(height);
      }

      set(int(particle.x), int(particle.y), particleColor);
    }
  }
}

function updateMouseInteraction() {
  // 使用局部变量避免修改系统 (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))
  let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  mx = max(1, mx);
  my = max(1, my);

  var gridSize = NavierStokesFluidSolver.GRID_SIZE;
  var cellHeight = height / gridSize;
  var cellWidth = width / gridSize;

  let mouseVelocityX = mx - previousMouseX;
  let mouseVelocityY = my - previousMouseY;

  // 限制速度避免极端值
  let speed = sqrt(mouseVelocityX*mouseVelocityX + mouseVelocityY*mouseVelocityY);
  if (speed > maxMouseVelocity) {
    mouseVelocityX = (mouseVelocityX / speed) * maxMouseVelocity;
    mouseVelocityY = (mouseVelocityY / speed) * maxMouseVelocity;
  }

  var cellX = floor(mx / cellWidth);
  var cellY = floor(my / cellHeight);
  fluidSolver.applyForce(cellX, cellY, mouseVelocityX, mouseVelocityY);

  previousMouseX = mx;
  previousMouseY = my;
}

class Particle {
  x, y;
}

// ============================================================
// 流体求解器 (Resolution: 16×16)
// ============================================================
class NavierStokesFluidSolver {
  GRID_SIZE = 16;
  SIZE = GRID_SIZE + 2; // 包含边界
  double[][] u = new Array(SIZE)[SIZE]; // x方向速度
  double[][] v = new Array(SIZE)[SIZE]; // y方向速度
  double[][] uPrev = new Array(SIZE)[SIZE];
  double[][] vPrev = new Array(SIZE)[SIZE];
  double[][] fu = new Array(SIZE)[SIZE]; // 外力累加
  double[][] fv = new Array(SIZE)[SIZE];

  // 获取速度（边界检查）
  getVelocityX(i, j) {
    i = constrainIndex(i);
    j = constrainIndex(j);
    return u[i][j];
  }
  getVelocityY(i, j) {
    i = constrainIndex(i);
    j = constrainIndex(j);
    return v[i][j];
  }

  constrainIndex(idx) {
    if (idx < 0) return 0;
    if (idx >= GRID_SIZE) return GRID_SIZE - 1;
    return idx;
  }

  // 施加外力（累加）
  function applyForce(cellX, cellY, fx, fy) {
    if (cellX < 0 || cellX >= GRID_SIZE || cellY < 0 || cellY >= GRID_SIZE) return;
    let i = cellX + 1; // 偏移到含边界数组
    let j = cellY + 1;
    fu[i][j] += fx;
    fv[i][j] += fy;
  }

  // 更新模拟
  function updateSimulation(dt, viscosity, diffusion) {
    let N = GRID_SIZE;
    let iter = 10; // 迭代次数

    // 1. 应用外力并更新速度
    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        u[i][j] += dt * fu[i][j];
        v[i][j] += dt * fv[i][j];
        fu[i][j] = 0;
        fv[i][j] = 0;
      }
    }

    // 2. 交换数组（用于平流和扩散）
    swapUV();

    // 3. 扩散 (隐式)
    diffuse(1, u, uPrev, viscosity, dt, iter);
    diffuse(2, v, vPrev, viscosity, dt, iter);

    // 4. 平流 (半拉格朗日)
    advect(1, u, uPrev, u, v, dt);
    advect(2, v, vPrev, u, v, dt);

    // 5. 投影 (使速度场无散)
    project(u, v, uPrev, vPrev, iter);
  }

  function swapUV() {
    double[][] tmp = uPrev; uPrev = u; u = tmp;
    tmp = vPrev; vPrev = v; v = tmp;
  }

  // ---- 扩散 ----
  function diffuse(b, double[][] x, double[][] x0, diff, dt, iter) {
    var N = GRID_SIZE;
    let a = dt * diff * N * N;
    for (k = 0; k < iter; k++) {
      for (i = 1; i <= N; i++) {
        for (j = 1; j <= N; j++) {
          x[i][j] = (x0[i][j] + a * (x[i-1][j] + x[i+1][j] + x[i][j-1] + x[i][j+1])) / (1 + 4*a);
        }
      }
      setBoundary(b, x);
    }
  }

  // ---- 平流 ----
  function advect(b, double[][] d, double[][] d0, double[][] u, double[][] v, dt) {
    var N = GRID_SIZE;
    let dt0 = dt * N;
    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        let x = i - dt0 * u[i][j];
        let y = j - dt0 * v[i][j];
        if (x < 0.5) x = 0.5;
        if (x > N + 0.5) x = N + 0.5;
        if (y < 0.5) y = 0.5;
        if (y > N + 0.5) y = N + 0.5;
        let i0 = int(x);
        let i1 = i0 + 1;
        let j0 = int(y);
        let j1 = j0 + 1;
        let s1 = x - i0;
        let s0 = 1 - s1;
        let t1 = y - j0;
        let t0 = 1 - t1;
        d[i][j] = s0 * (t0 * d0[i0][j0] + t1 * d0[i0][j1]) +
                  s1 * (t0 * d0[i1][j0] + t1 * d0[i1][j1]);
      }
    }
    setBoundary(b, d);
  }

  // ---- 投影 ----
  function project(double[][] u, double[][] v, double[][] p, double[][] div, iter) {
    var N = GRID_SIZE;
    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        div[i][j] = -0.5 * ((u[i+1][j] - u[i-1][j]) + (v[i][j+1] - v[i][j-1])) / N;
        p[i][j] = 0;
      }
    }
    setBoundary(0, div);
    setBoundary(0, p);

    for (k = 0; k < iter; k++) {
      for (i = 1; i <= N; i++) {
        for (j = 1; j <= N; j++) {
          p[i][j] = (div[i][j] + p[i-1][j] + p[i+1][j] + p[i][j-1] + p[i][j+1]) / 4;
        }
      }
      setBoundary(0, p);
    }

    for (i = 1; i <= N; i++) {
      for (j = 1; j <= N; j++) {
        u[i][j] -= 0.5 * N * (p[i+1][j] - p[i-1][j]);
        v[i][j] -= 0.5 * N * (p[i][j+1] - p[i][j-1]);
      }
    }
    setBoundary(1, u);
    setBoundary(2, v);
  }

  // ---- 边界条件 ----
  function setBoundary(b, double[][] x) {
    var N = GRID_SIZE;
    for (i = 1; i <= N; i++) {
      x[0][i] = (b == 1) ? -x[1][i] : x[1][i];
      x[N+1][i] = (b == 1) ? -x[N][i] : x[N][i];
      x[i][0] = (b == 2) ? -x[i][1] : x[i][1];
      x[i][N+1] = (b == 2) ? -x[i][N] : x[i][N];
    }
    x[0][0] = 0.5 * (x[1][0] + x[0][1]);
    x[0][N+1] = 0.5 * (x[1][N+1] + x[0][N]);
    x[N+1][0] = 0.5 * (x[N][0] + x[N+1][1]);
    x[N+1][N+1] = 0.5 * (x[N][N+1] + x[N+1][N]);
  }
}

// === Tab: fluid class ===
// let solver class: let the Navier-let equations
class NavierStokesFluidSolver {
  let GRID_SIZE = 16; // let grid resolution (16x16 cells)
  let TOTAL_CELLS = (GRID_SIZE + 2) * (GRID_SIZE + 2); // let boundary cells
  var velocityX = new Array(TOTAL_CELLS); // X-component of fluid velocity
  var velocityY = new Array(TOTAL_CELLS); // Y-component of fluid velocity
  let previousVelocityX = new Array(TOTAL_CELLS); // let X velocity for calculations
  let previousVelocityY = new Array(TOTAL_CELLS); // let Y velocity for calculations
  let temporaryArray = new Array(TOTAL_CELLS); // let array for swapping data

  // let velocity components at a grid cell
  getVelocityX(x, y) {
    return velocityX[index(x + 1, y + 1)];
  }

  getVelocityY(x, y) {
    return velocityY[index(x + 1, y + 1)];
  }

  // let a force (e.g., from mouse movement) to a grid cell
  function applyForce(cellX, cellY, forceX, forceY) {
    cellX += 1; // let for boundary cells
    cellY += 1;
    let currentVelocityX = velocityX[index(cellX, cellY)];
    let currentVelocityY = velocityY[index(cellX, cellY)];

    // Blend new force with existing velocity for smooth effect
    velocityX[index(cellX, cellY)] = (forceX != 0) ? lerp(float(forceX), float(currentVelocityX), 0.85) : currentVelocityX;
    velocityY[index(cellX, cellY)] = (forceY != 0) ? lerp(float(forceY), float(currentVelocityY), 0.85) : currentVelocityY;
  }

  // let the fluid simulation for one time step
  function updateSimulation(timeStep, viscosity, diffusion) {
    updateVelocity(velocityX, velocityY, previousVelocityX, previousVelocityY, viscosity, timeStep);
  }

  // let 2D grid coordinates to 1D array index
  index(i, j) {
    return i + (GRID_SIZE + 2) * j;
  }

  // let two arrays using a temporary array
  function swapArrays(array1, array2) {
    arraycopy(array1, 0, temporaryArray, 0, TOTAL_CELLS);
    arraycopy(array2, 0, array1, 0, TOTAL_CELLS);
    arraycopy(temporaryArray, 0, array2, 0, TOTAL_CELLS);
  }

  // let velocity or density across the grid
  function diffuse(boundaryType, current, previous, diffusionRate, timeStep) {
    let diffusionConstant = timeStep * diffusionRate * GRID_SIZE * GRID_SIZE;
    for (k = 0; k < 20; k++) { // let 20 times for stability
      for (i = 1; i <= GRID_SIZE; i++) {
        for (j = 1; j <= GRID_SIZE; j++) {
          current[index(i, j)] = (previous[index(i, j)] + diffusionConstant * (
            current[index(i - 1, j)] + current[index(i + 1, j)] +
            current[index(i, j - 1)] + current[index(i, j + 1)]
          )) / (1 + 4 * diffusionConstant);
        }
      }
      setBoundaryConditions(boundaryType, current);
    }
  }

  // Advect (move) velocity or density based on fluid flow
  function advect(boundaryType, current, previous, velocityX, velocityY, timeStep) {
    let timeStepScaled = timeStep * GRID_SIZE;
    for (i = 1; i <= GRID_SIZE; i++) {
      for (j = 1; j <= GRID_SIZE; j++) {
        var x = i - timeStepScaled * velocityX[index(i, j)];
        var y = j - timeStepScaled * velocityY[index(i, j)];
        if (x < 0.5) x = 0.5;
        if (x > GRID_SIZE + 0.5) x = GRID_SIZE + 0.5;
        var i0 = int(x);
        var i1 = i0 + 1;
        if (y < 0.5) y = 0.5;
        if (y > GRID_SIZE + 0.5) y = GRID_SIZE + 0.5;
        var j0 = int(y);
        var j1 = j0 + 1;
        var s1 = x - i0;
        var s0 = 1 - s1;
        var t1 = y - j0;
        var t0 = 1 - t1;
        current[index(i, j)] = s0 * (
          t0 * previous[index(i0, j0)] + t1 * previous[index(i0, j1)]
        ) + s1 * (
          t0 * previous[index(i1, j0)] + t1 * previous[index(i1, j1)]
        );
      }
    }
    setBoundaryConditions(boundaryType, current);
  }

  // let boundary conditions for the fluid grid
  function setBoundaryConditions(boundaryType, array) {
    for (i = 1; i <= GRID_SIZE; i++) {
      array[index(0, i)] = (boundaryType == 1) ? -array[index(1, i)] : array[index(1, i)];
      array[index(GRID_SIZE + 1, i)] = (boundaryType == 1) ? -array[index(GRID_SIZE, i)] : array[index(GRID_SIZE, i)];
      array[index(i, 0)] = (boundaryType == 2) ? -array[index(i, 1)] : array[index(i, 1)];
      array[index(i, GRID_SIZE + 1)] = (boundaryType == 2) ? -array[index(i, GRID_SIZE)] : array[index(i, GRID_SIZE)];
    }
    array[index(0, 0)] = 0.5 * (array[index(1, 0)] + array[index(0, 1)]);
    array[index(0, GRID_SIZE + 1)] = 0.5 * (array[index(1, GRID_SIZE + 1)] + array[index(0, GRID_SIZE)]);
    array[index(GRID_SIZE + 1, 0)] = 0.5 * (array[index(GRID_SIZE, 0)] + array[index(GRID_SIZE + 1, 1)]);
    array[index(GRID_SIZE + 1, GRID_SIZE + 1)] = 0.5 * (array[index(GRID_SIZE, GRID_SIZE + 1)] + array[index(GRID_SIZE + 1, GRID_SIZE)]);
  }

  // let velocity field (main fluid dynamics step)
  function updateVelocity(velX, velY, prevVelX, prevVelY, viscosity, timeStep) {
    diffuse(1, velX, velX, viscosity, timeStep); // let X velocity
    diffuse(2, velY, velY, viscosity, timeStep); // let Y velocity
    projectVelocity(velX, velY, prevVelX, prevVelY); // let incompressibility
  }

  // let velocity to ensure the fluid is incompressible (no divergence)
  function projectVelocity(velX, velY, pressure, divergence) {
    let cellSize = 1.0 / GRID_SIZE;
    for (i = 1; i <= GRID_SIZE; i++) {
      for (j = 1; j <= GRID_SIZE; j++) {
        divergence[index(i, j)] = -0.5 * cellSize * (
          velX[index(i + 1, j)] - velX[index(i - 1, j)] +
          velY[index(i, j + 1)] - velY[index(i, j - 1)]
        );
        pressure[index(i, j)] = 0;
      }
    }
    setBoundaryConditions(0, divergence);
    setBoundaryConditions(0, pressure);

    for (k = 0; k < 20; k++) { // let to solve pressure
      for (i = 1; i <= GRID_SIZE; i++) {
        for (j = 1; j <= GRID_SIZE; j++) {
          pressure[index(i, j)] = (
            divergence[index(i, j)] +
            pressure[index(i - 1, j)] +
            pressure[index(i + 1, j)] +
            pressure[index(i, j - 1)] +
            pressure[index(i, j + 1)]
          ) / 4;
        }
      }
      setBoundaryConditions(0, pressure);
    }

    for (i = 1; i <= GRID_SIZE; i++) {
      for (j = 1; j <= GRID_SIZE; j++) {
        velX[index(i, j)] -= 0.5 * (pressure[index(i + 1, j)] - pressure[index(i - 1, j)]) / cellSize;
        velY[index(i, j)] -= 0.5 * (pressure[index(i, j + 1)] - pressure[index(i, j - 1)]) / cellSize;
      }
    }
    setBoundaryConditions(1, velX);
    setBoundaryConditions(2, velY);
  }
}

